use std::collections::BTreeSet;

pub fn folded(x:u64,q:u64)->u64{let r=x%q;r.min(q-r)}
pub fn m13(c:u32)->Vec<u64>{let q=1u64<<c;assert!(c>=3);(0..=q/2).filter(|&b|b==0||matches!((b>>b.trailing_zeros())%8,1|7)).collect()}
pub fn m123(c:u32)->Vec<u64>{assert!(c>=4);match c{4=>vec![0,1,2,4,7],5=>vec![0,1,3,4,5,7,8,13],_=>{let q=1u64<<c;let h=q/8;let mut set=BTreeSet::from([1]);let mut power=1u64;for j in 0..q/4{if(j>=1&&j<h&&j%2==1)||(j>=h&&(j-h)%2==0){set.insert(folded(power,q));}power=power*3%q;}set.extend(m123(c-2).into_iter().map(|b|4*b));set.into_iter().collect()}}}
pub fn gap(b:&[u64])->u64{b.windows(2).map(|x|x[1]-x[0]).max().unwrap_or(0)}

#[derive(Debug,Clone,Copy)]pub struct Digit{pub sign:i64,pub multiplier:i64,pub bucket:i64,pub carry:i64}
pub fn decompose(t:i64,c:u32)->Digit{let q=1i64<<c;assert!(c>=3&&(-1..=q+1).contains(&t));let residue=t.rem_euclid(q);let x=residue.min(q-residue);if x==0{return Digit{sign:1,multiplier:1,bucket:0,carry:t/q};}let odd=x>>x.trailing_zeros();let m=if matches!(odd%8,1|7){1}else{3};let b=if m==1{x}else{let inv=if q%3==1{(2*q+1)/3}else{(q+1)/3};let z=residue*inv%q;z.min(q-z)};let sign=if(m*b).rem_euclid(q)==residue{1}else{-1};let carry=(t-sign*m*b)/q;assert_eq!(t,sign*m*b+carry*q);assert!((-1..=2).contains(&carry));Digit{sign,multiplier:m,bucket:b,carry}}
pub fn extract(words:[u64;4],shift:usize,c:u32)->u64{if shift>=256{return 0;}let i=shift/64;let s=shift%64;let mut v=words[i]>>s;if s>0&&i<3{v|=words[i+1]<<(64-s);}v&((1u64<<c)-1)}
pub fn recode(words:[u64;4],c:u32)->Vec<i64>{assert!(words[3]<(1<<62));let h=254usize.div_ceil(c as usize);let mut carry=0;let mut result=Vec::with_capacity(h+1);for j in 0..h{let d=decompose(extract(words,j*c as usize,c)as i64+carry,c);result.push(d.sign*d.multiplier*d.bucket);carry=d.carry;}result.push(carry);result}

// Independent fixed-width signed accumulator. All model terms fit far below384bits.
pub fn reconstruct(digits:&[i64],c:u32)->[u64;6]{let mut acc=[0u64;6];for(i,&d)in digits.iter().enumerate(){let mut term=[0u64;6];let shift=i*c as usize;assert!(shift+32<384);let limb=shift/64;let offset=shift%64;let value=d.unsigned_abs();term[limb]=value<<offset;if offset>0&&limb+1<6{term[limb+1]=value>>(64-offset);}if d<0{for t in&mut term{*t=!*t;}let mut carry=1u128;for t in&mut term{let v=*t as u128+carry;*t=v as u64;carry=v>>64;}}let mut carry=0u128;for(j,t)in term.into_iter().enumerate(){let v=acc[j]as u128+t as u128+carry;acc[j]=v as u64;carry=v>>64;}}acc}
pub fn inputs()->Vec<[u64;4]>{let r=[0x43e1f593f0000001u64,0x2833e84879b97091,0xb85045b68181585d,0x30644e72e131a029];let mut result=vec![[0;4],[1,0,0,0],r];let mut below=r;below[0]-=1;result.push(below);let mut above=r;above[0]+=1;result.push(above);for bit in 0..254{let mut p=[0u64;4];p[bit/64]=1u64<<(bit%64);result.push(p);let mut lo=p;let mut borrow=true;for x in&mut lo{if borrow{let(v,b)=x.overflowing_sub(1);*x=v;borrow=b;}}result.push(lo);let mut hi=p;let mut carry=true;for x in&mut hi{if carry{let(v,b)=x.overflowing_add(1);*x=v;carry=b;}}result.push(hi);}let mut seed=0x4c464732373530u64;for _ in 0..16384{let mut w=[0;4];for v in&mut w{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;*v=seed;}w[3]&=(1u64<<62)-1;result.push(w);}result}
pub fn validate_sets()->Vec<serde_json::Value>{let mut rows=Vec::new();for c in 4..=18{let q=1u64<<c;for(name,multipliers,buckets)in[("M13",vec![1,3],m13(c)),("M123",vec![1,2,3],m123(c))]{assert_eq!(buckets.first(),Some(&0));assert!(buckets.windows(2).all(|b|b[0]<b[1]));let count=if name=="M13"{q/4+2}else{q.div_ceil(6)+c as u64/2};assert_eq!(buckets.len()as u64,count);let mut cover=vec![false;(q/2+1)as usize];for &m in&multipliers{for &b in&buckets{assert!(b<=q/2);cover[folded(m*b,q)as usize]=true;}}assert!(cover.into_iter().all(|v|v));rows.push(serde_json::json!({"c":c,"radix":q,"set":name,"cardinality":buckets.len(),"max_gap":gap(&buckets),"all_centered_residues_covered":true}));}}rows}

#[cfg(test)]mod tests{
 use super::*;
 #[test]fn constructors_cover_residues_and_exact_cardinalities(){let rows=validate_sets();assert_eq!(rows.len(),30);let gaps=[16u64,18,16,21,15,19,22,31,24];for row in rows{let c=row["c"].as_u64().unwrap();if(10..=18).contains(&c){assert_eq!(row["max_gap"],if row["set"]=="M13"{5}else{gaps[(c-10)as usize]});}}}
 #[test]fn table_free_conversion_exhausts_all_updated_digits(){for c in 4..=18{let q=1u64<<c;let allowed=m13(c).into_iter().collect::<BTreeSet<_>>();for t in -1..=q as i64+1{let d=decompose(t,c);assert!(allowed.contains(&(d.bucket as u64)));assert!(matches!(d.multiplier,1|3));assert!(matches!(d.sign,-1|1));assert_eq!(t,d.sign*d.multiplier*d.bucket+d.carry*q as i64);}}}
 #[test]fn full_width_exact_reconstruction_and_independent_group_sums(){let values=inputs();for c in[10,12,14]{for w in&values{let digits=recode(*w,c);let got=reconstruct(&digits,c);assert_eq!(&got[..4],w);assert_eq!(got[4..],[0,0]);}for modulus in[101i128,65537]{for(i,w)in values.iter().take(1024).enumerate(){let coefficient=(i+1)as i128;let mut direct=0i128;for limb in w.iter().rev(){direct=(direct*((1i128<<64)%modulus)+*limb as i128)%modulus;}let mut converted=0i128;for d in recode(*w,c).into_iter().rev(){converted=(converted*(1i128<<c)+d as i128).rem_euclid(modulus);}assert_eq!((direct*coefficient)%modulus,(converted*coefficient)%modulus);}}}}
}

fn main(){let root="/home/ubuntu/src/zopro-perf-work/lfg-power-two176";let rows=validate_sets();let values=inputs();let mut carries=Vec::new();for c in[10,12,14]{let mut counts=[0usize;4];for &w in&values{let digits=recode(w,c);let got=reconstruct(&digits,c);assert_eq!(got,[w[0],w[1],w[2],w[3],0,0]);counts[(*digits.last().unwrap()+1)as usize]+=1;}carries.push(serde_json::json!({"width":c,"full_width_inputs":values.len(),"final_carry_minus1_0_1_2":counts}));}let counts:serde_json::Value=serde_json::from_slice(&std::fs::read(format!("{root}/input-counts.json")).unwrap()).unwrap();let mut payloads=Vec::new();for(case,queries)in counts["cases"].as_object().unwrap(){for(name,q)in queries.as_object().unwrap(){let n=q["n"].as_u64().unwrap();let affine=if name=="A"{64}else{128};let h=254u64.div_ceil(12);let base=n*affine;payloads.push(serde_json::json!({"case":case,"query":name,"points":n,"affine_bytes":affine,"width":12,"full_scalar_bits":254,"windows":h,"original_point_payload_bytes":base,"M13_strategy_I_points":2*h*n,"M13_strategy_I_payload_bytes":2*h*base,"M13_strategy_II_payload_bytes":(2*h+1)*base,"M123_strategy_I_payload_bytes":3*h*base,"M123_strategy_II_payload_bytes":(3*h+1)*base,"not_RSS_or_actual_allocation":true}));}}let result=serde_json::json!({"complete":true,"bucket_sets":rows,"conversion":carries,"exact_reconstructions":values.len()*3,"memory_payloads":payloads,"production_changed":false,"new_SDK_requests":0,"new_Gnark_exports":0,"proof_ledger":29461,"adopted":false,"goal_achieved":false,"paper_full_table_rejected_for_architecture":true,"bounded_Horner_variant_not_implemented":true,"new_latency_claim":false});std::fs::write(format!("{root}/analysis.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("30exactbucketsets;{}fullwidthreconstructions;16querypayloads;no nativeMSM/proof/performanceclaim;ledger29461unchanged",values.len()*3);}
